+bool _probeNativeJsEngine() {
+  try {
+    if (Platform.isMacOS || Platform.isIOS) {
+      // flutter_js picks JavascriptCoreRuntime on Apple desktops/devices;
+      // jsc_ffi.dart dlopens the system framework with this fallback chain.
+      DynamicLibrary lib;
