for p in glob.glob('lib/services/agent_service_*.dart'):
    text = open(p).read()
    if 'extension ' not in text:
        continue
    names = set()
    for m in re.finditer(r'^  (?:[\w<>?\[\], ]+ )?(\w+)\(', text, re.M):
        names.add(m.group(1))
    for m in re.finditer(r'^  [\w<>?, ]+? get (\w+)', text, re.M):
        names.add(m.group(1))
    for m in re.finditer(r'^  set (\w+)', text, re.M):
        names.add(m.group(1))
    for n in sorted(names & class_members):
        dups.setdefault(n, []).append(p)

for k, v in sorted(dups.items()):
    print('DUP:', k, '<-', ', '.join(v))
if not dups:
    print('no dups')
