import re, subprocess, glob

def members_of(text):
    # map member-name -> body text from 2-space-indented declarations to next 2-space declaration
    lines = text.split('\n')
    mem = {}
    cur_name = None
    cur_lines = []
    decl = re.compile(r'^  (?:[\w<>?\[\],@ ]+ )?(?:get |set )?(\w+)[({=;]')
    for ln in lines:
        if ln.startswith('  ') and not ln.startswith('    ') and decl.match(ln) and not ln.strip().startswith('//'):
            if cur_name: mem[cur_name] = '\n'.join(cur_lines)
            cur_name = decl.match(ln).group(1)
            cur_lines = [ln]
        else:
            if cur_name is not None:
                cur_lines.append(ln)
    if cur_name: mem[cur_name] = '\n'.join(cur_lines)
    return mem

head_class = open('lib/services/agent_service.dart').read()
hm = members_of(head_class)

for p in sorted(glob.glob('lib/services/agent_service_*.dart')):
    text = open(p).read()
    if 'extension ' not in text: continue
    pm = members_of(text)
    main_text = subprocess.run(['git','--no-pager','show',f'origin/main:flutter_app/{p}'],capture_output=True,text=True).stdout
    mm = members_of(main_text) if main_text else {}
    for name in sorted(set(hm) & set(pm)):
        if name in ('_notify','unawaited','debugPrint'): continue
        in_main_class = re.search(rf'^  .* {name}[({=;]', subprocess.run(['git','--no-pager','show','origin/main:flutter_app/lib/services/agent_service.dart'],capture_output=True,text=True).stdout, re.M)
        main_side = 'main-class' if in_main_class else 'main-part'
        head_body = re.sub(r'\s+',' ',hm[name])
        main_body = re.sub(r'\s+',' ',mm.get(name,''))
        same = 'SAME' if head_body==main_body else '*** DIVERGES ***'
        print(f'{name:35s} {p.split("/")[-1]:35s} live-on={main_side:10s} {same}')
EOF"}

