+  /// the routing fallback then keeps the notice (delivery, not drop).
+  Future<String?> _appBoundSessionId(String appId) async {
+    try {
+      final raw = await env.readTextFile('apps/$appId/session.json');
+      final text = raw.valueOrNull;
