import re, glob

def member_spans(text):
    lines = text.split('\n')
    spans = {}
    cur_name = None; start = None
    decl = re.compile(r'^  (?:[\w<>?\[\],@ ]+ )?(?:get |set )?(\w+)[({=;]')
    for i, ln in enumerate(lines):
        if ln.startswith('  ') and not ln.startswith('    ') and decl.match(ln) and not ln.strip().startswith('//'):
            if cur_name: spans.setdefault(cur_name, []).append((start, i))
            cur_name = decl.match(ln).group(1); start = i
        elif cur_name is not None and not ln.startswith('    ') and ln.strip() and not ln.startswith('  '):
            spans.setdefault(cur_name, []).append((start, i)); cur_name=None
    if cur_name: spans.setdefault(cur_name, []).append((start, len(lines)))
    return spans, len(lines)

head = open('lib/services/agent_service.dart').read()
hs, total = member_spans(head)
ext_names = set()
for p in glob.glob('lib/services/agent_service_*.dart'):
    t = open(p).read()
    if 'extension ' not in t: continue
    for m in re.finditer(r'^  (?:[\w<>?\[\],@ ]+ )?(?:get |set )?(\w+)[({=;]', t, re.M):
        ext_names.add(m.group(1))

dup_lines = 0
for name, spans in hs.items():
    if name in ext_names and name not in ('_notify','unawaited','debugPrint'):
        for a,b in spans: dup_lines += b-a
print('total lines:', total, ' shadow-duplicated member lines:', dup_lines)
