+    }
+    engine = (engineFactory ?? smokeProbeEngineFactory)(
+      app: app,
+      env: scratch,
+      permissions: app.declaredPermissions,
+      entryFile: JsAppEngine.defaultEntryFile,
+      errorSink: (event) => errors.add(
