import 'dart:io';

void main() {
  final lib = File('lib/services/agent_service.dart').readAsStringSync();
  // naive class-level member parse: lines at 2-space indent declaring members
  final classMembers = <String>{};
  for (final m in RegExp(r'^  (?:[\\w<>?\\[\\]]+ )?(\\w+)\\(', multiLine: true).allMatches(lib)) {
    classMembers.add(m.group(1)!);
  }
  for (final f in RegExp(r'^  (?:final|var|String|bool|int|double|Map|List|Set|Stream|Future|[\\w<>?, ]+?) (\\w+)[;=]', multiLine: true).allMatches(lib)) {
    classMembers.add(f.group(1)!);
  }
  final parts = Directory('lib/services').listSync().whereType<File>().where((f) => f.path.contains('agent_service_'));
  final dups = <String, List<String>>{};
  for (final p in parts) {
    final text = p.readAsStringSync();
    if (!text.contains('extension ')) continue;
    for (final m in RegExp(r'^  (?:[\\w<>?\\[\\]]+ )?(\\w+)\\(', multiLine: true).allMatches(text)) {
      final name = m.group(1)!;
      if (classMembers.contains(name)) {
        dups.putIfAbsent(name, () => []).add(p.path);
      }
    }
    for (final g in RegExp(r'^  (?:[\\w<>?, ]+?) get (\\w+)', multiLine: true).allMatches(text)) {
      final name = g.group(1)!;
      if (classMembers.contains(name)) {
        dups.putIfAbsent(name, () => []).add(p.path);
      }
    }
    for (final s in RegExp(r'^  set (\\w+)', multiLine: true).allMatches(text)) {
      final name = s.group(1)!;
      if (classMembers.contains(name)) {
        dups.putIfAbsent(name, () => []).add(p.path);
