final _engineSkip = quickJsBridgeAvailable ? false : kQuickJsBridgeUnavailable;

JsAppInfo _app() => JsAppInfo.fromManifest(
  const {'id': 'demo', 'name': 'Demo'},
  bundled: false,
  fallbackId: 'demo',
);

