        runAppPreflight(appId, env);
    final registry = _toolRegistry;
    if (registry != null) {
      if (launcher == null) {
        registry.unregister(openAppToolName);
      } else {
        registry.register(
          openAppTool(env, launcher: launcher, preflight: gate),
