import re, subprocess, glob

def members_of(text):
    # map member-name -> body text from 2-space-indented declarations to next 2-space declaration
    lines = text.split('\n')
    mem = {}
    cur_name = None
    cur_lines = []
    decl = re.compile(r'^  (?:[\w<>?\[\],@ ]+ )?(?:get |set )?(\w+)[({=;]')
    for ln in lines:
        if ln.startswith('  ') and not ln.startswith('    ') and decl.match(ln) and not ln.strip().startswith('//'):
            if cur_name: mem[cur_name] = '\n'.join(cur_lines)
            cur_name = decl.match(ln).group(1)
            cur_lines = [ln]
        else:
            if cur_name is not None:
                cur_lines.append(ln)
    if cur_name: mem[cur_name] = '\n'.join(cur_lines)
    return mem

