    if (launcher == _appLauncher) return;
    _appLauncher = launcher;
    Future<AppPreflightOutcome?> gate(String appId) =>
        runAppPreflight(appId, env);
    final registry = _toolRegistry;
    if (registry != null) {
      if (launcher == null) {
        registry.unregister(openAppToolName);
      } else {
        registry.register(
